#!/usr/bin/env python3
"""Converts CSV, JSON, or pipe-delimited text into Markdown and HTML tables."""

import json
import sys
from typing import Any, List, Tuple


def detect_format(text: str) -> str:
    """Return 'json', 'pipe', or 'csv' based on text inspection."""
    stripped = text.strip()
    if stripped.startswith('['):
        return 'json'
    first_line = stripped.split('\n')[0].strip()
    if '|' in first_line and ',' not in first_line:
        return 'pipe'
    return 'csv'


def is_numeric(value: str) -> bool:
    """Check if a string can be interpreted as int or float."""
    try:
        float(value)
        return True
    except ValueError:
        return False


def parse_input(text: str) -> Tuple[List[str], List[List[str]], str]:
    """Return (header, rows, fmt) where fmt is 'csv', 'pipe', or 'json'."""
    fmt = detect_format(text)
    text = text.strip()
    if fmt == 'json':
        data = json.loads(text)
        if not data or not isinstance(data, list):
            raise ValueError("JSON must be a non-empty list of objects")
        header = list(data[0].keys())
        rows = [[str(row.get(col, '')) for col in header] for row in data]
    elif fmt == 'pipe':
        lines = text.split('\n')
        header = [h.strip() for h in lines[0].split('|')]
        rows = []
        for line in lines[1:]:
            if line.strip():
                rows.append([cell.strip() for cell in line.split('|')])
    else:  # csv
        lines = text.split('\n')
        header = [h.strip() for h in lines[0].split(',')]
        rows = []
        for line in lines[1:]:
            if line.strip():
                rows.append([cell.strip() for cell in line.split(',')])
    return header, rows, fmt


def align_right(header: List[str], rows: List[List[str]]) -> List[bool]:
    """Return list of booleans indicating which columns should be right-aligned."""
    num_cols = len(header)
    if num_cols == 0:
        return []
    aligns = []
    for col_idx in range(num_cols):
        all_numeric = True
        for row in rows:
            if col_idx < len(row):
                val = row[col_idx].strip()
                if val == '' or not is_numeric(val):
                    all_numeric = False
                    break
            else:
                all_numeric = False
                break
        aligns.append(all_numeric)
    return aligns


def generate_markdown(header: List[str], rows: List[List[str]], aligns: List[bool]) -> str:
    """Generate Markdown table as string."""
    lines = []
    # Header
    header_line = '| ' + ' | '.join(header) + ' |'
    lines.append(header_line)
    # Separator
    sep_parts = []
    for a in aligns:
        if a:
            sep_parts.append('---:')
        else:
            sep_parts.append(':---')
    sep_line = '| ' + ' | '.join(sep_parts) + ' |'
    lines.append(sep_line)
    # Data rows
    for row in rows:
        padded = row + [''] * (len(header) - len(row))
        data_line = '| ' + ' | '.join(padded) + ' |'
        lines.append(data_line)
    return '\n'.join(lines)


def generate_html(header: List[str], rows: List[List[str]], aligns: List[bool]) -> str:
    """Generate HTML table as string."""
    lines = ['<table>']
    # thead
    lines.append('  <thead>')
    lines.append('    <tr>')
    for i, h in enumerate(header):
        align_attr = ' align="right"' if aligns[i] else ''
        lines.append(f'      <th{align_attr}>{h}</th>')
    lines.append('    </tr>')
    lines.append('  </thead>')
    # tbody
    lines.append('  <tbody>')
    for row in rows:
        lines.append('    <tr>')
        for i in range(len(header)):
            val = row[i] if i < len(row) else ''
            align_attr = ' align="right"' if aligns[i] else ''
            lines.append(f'      <td{align_attr}>{val}</td>')
        lines.append('    </tr>')
    lines.append('  </tbody>')
    lines.append('</table>')
    return '\n'.join(lines)


def generate_error_report(header: List[str], rows: List[List[str]]) -> str:
    """Return error report for rows with wrong field count, or empty string."""
    expected = len(header)
    bad_rows = []
    for idx, row in enumerate(rows, start=1):
        if len(row) != expected:
            bad_rows.append((idx, '|'.join(row)))
    if not bad_rows:
        return ''
    report_parts = ['Rows with wrong number of fields:']
    for idx, content in bad_rows:
        report_parts.append(f'Row {idx}: {content}')
    return '\n'.join(report_parts)


def convert(text: str) -> dict:
    """Return dict with keys 'markdown', 'html', 'error_report'."""
    header, rows, _ = parse_input(text)
    aligns = align_right(header, rows)
    markdown = generate_markdown(header, rows, aligns)
    html = generate_html(header, rows, aligns)
    error_report = generate_error_report(header, rows)
    return {'markdown': markdown, 'html': html, 'error_report': error_report}
